import{j as t}from"./blog-pages-Bhdy2a24.js";import{I as e}from"./I18nErpPage-DA6e3rVp.js";import"./PillarHubNav-DX4b9s1z.js";import"./badge-iM67T618.js";const i={heroBadge:"نظام إدارة فحوصات الاختبارات غير المتلفة",heroTitle:"برنامج تخطيط موارد المؤسسات للاختبارات غير المتلفة في الرياض",heroSubtitle:"حل متكامل لإدارة فحص الأصول",heroIntro:"نظام تخطيط موارد مصمم لشركات الاختبارات غير المتلفة في الرياض. أتمتة متابعة شهادات ASNT، وجدولة فحوصات سعودي أرامكو، وإصدار تقارير PDF بصيغة SAEP-1142 خلال دقائق.",ctaPrimary:"اطلب عرضًا توضيحيًا للرياض",ctaSecondary:"English version",statCompanies:"شركة فحص تستخدم النظام",statRating:"متوسط تقييم العملاء",statAdminReduction:"تقليل الوقت الإداري",statModules:"وحدات رئيسية",marketContextLabel:"سياق سوق الاختبارات غير المتلفة",painPointsTitle:"لماذا تختار فرق الاختبارات غير المتلفة في الرياض نظام أتلانتيس؟",painPointsSubtitle:"ثلاث نقاط ألم تشغيلية حرجة يتم القضاء عليها منذ اليوم الأول",problemLabel:"المشكلة",solutionLabel:"الحل",modulesTitle:"ست وحدات أساسية لشركات الاختبارات غير المتلفة",modulesSubtitle:"كل وحدة مصممة خصيصًا لقطاع التفتيش الصناعي",roiTitle:"العائد على الاستثمار في الرياض",faqTitle:"الأسئلة الشائعة — نظام أتلانتيس في الرياض",alsoServingTitle:"خدمات أخرى",finalCtaTitle:"هل أنت مستعد لتحديث عمليات الاختبارات غير المتلفة في الرياض؟",finalCtaBody:"انضم إلى شركات التفتيش في الرياض وضواحيها الصناعية التي استبدلت جداول البيانات بنظام أتلانتيس.",finalCtaPrimary:"اطلب عرضًا توضيحيًا",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function s(){return t.jsx(e,{lang:"ar",dir:"rtl",city:"الرياض",countryCode:"SA",countryName:"المملكة العربية السعودية",slug:"ndt-erp-riyadh",canonicalPath:"/ar/ndt-erp-riyadh",englishPath:"/ndt-erp-saudi-arabia",pageTitle:"برنامج NDT في الرياض | نظام إدارة الفحص الصناعي | أتلانتيس NDT",pageDescription:"نظام تخطيط موارد للاختبارات غير المتلفة لشركات الفحص في الرياض. متابعة شهادات ASNT، جدولة API 510 و API 570، تقارير متوافقة مع سعودي أرامكو SAEP-1142.",keywords:"برنامج NDT الرياض, نظام إدارة فحص, ASNT, API 510, سعودي أرامكو, SAEP-1142, الهيئة العامة للأرصاد والبيئة, ساسو",marketContext:"تعمل شركات الاختبارات غير المتلفة في الرياض في بيئة فريدة تجمع بين مقرات شركات النفط والغاز الكبرى وأصول الطاقة المتجددة الناشئة في مشاريع نيوم والبحر الأحمر، إلى جانب البنية التحتية الصناعية المتسارعة النمو في المدن الصناعية الحديثة بالضواحي. يجب على شركات الفحص في الرياض الالتزام بمتطلبات تأهيل المفتشين لدى شركة سعودي أرامكو وفق معيار SAEP-1112، ومتطلبات سلامة العمليات الصادرة عن الهيئة العامة للأرصاد وحماية البيئة، فضلًا عن متطلبات الجودة الخاصة بالعملاء الصناعيين الجدد مثل شركة معادن وشركة الطاقة الكهربائية. يوفر نظام أتلانتيس لتخطيط موارد الاختبارات غير المتلفة لفرق الفحص في الرياض منصة موحدة لمتابعة شهادات ASNT و ISO 9712، وجدولة فحوصات API 510 للأوعية الضاغطة و API 570 للأنابيب و API 653 لخزانات التخزين، وإصدار تقارير PDF متعددة اللغات (العربية والإنجليزية) متوافقة مع متطلبات سعودي أرامكو SAEP-1142 و SAEP-1106. كما يدعم النظام تكامل بوابة موردي أرامكو وسير عمل الموافقة على المفتشين قبل التعبئة لمشاريع جديدة في الرياض والمناطق المجاورة.",roiBody:"تشير بيانات شركات الفحص في الرياض التي اعتمدت نظام أتلانتيس إلى تقليل الوقت الإداري بنسبة 40% خلال أول ستة أشهر من النشر، وانخفاض زمن إعداد تقرير API 570 من ثلاث ساعات ونصف إلى أقل من خمس دقائق. كما يختفي خطر انتهاء شهادات ASNT المفاجئ بفضل التنبيهات الآلية قبل 90 و60 و30 يومًا. لفريق فحص مكوّن من خمسة عشر فنيًا يخدم عملاء في الرياض، يمثل ذلك توفيرًا سنويًا يقارب 90,000 ريال سعودي في الوقت الإداري، قبل احتساب القيمة الوقائية لتجنب فقدان أهلية العقود مع شركة معادن وشركة الكهرباء السعودية.",painPoints:[{title:"متطلبات سعودي أرامكو المعقدة",problem:"تواجه شركات الفحص في الرياض تحدي الالتزام بصيغ تقارير سعودي أرامكو SAEP-1142 ومتطلبات تأهيل المفتشين SAEP-1112، التي تتغير دوريًا وتصعب متابعتها يدويًا.",solution:"يحتوي نظام أتلانتيس على قوالب تقارير معتمدة مسبقًا متوافقة مع SAEP-1142، مع تحديثات تلقائية عند صدور إصدارات جديدة من المعايير."},{title:"إدارة الفنيين في مواقع متفرقة",problem:"تدير شركات الفحص في الرياض فرقًا تعمل في مواقع متفرقة بين بقيق ورأس تنورة والجبيل، مما يصعّب على المشرفين معرفة توفر الفنيين في الوقت الفعلي.",solution:"لوحة قيادة فورية تعرض مواقع الفنيين ومدد المهام والشهادات المعتمدة لكل عميل، مع إمكانية إعادة جدولة فورية."},{title:"التدقيق الفصلي لأرامكو",problem:"تكشف عمليات تدقيق أرامكو الفصلية في الرياض عن شركات تفتيش تفتقر إلى سجلات منظمة وفورية الوصول لمؤهلات الموظفين وسجلات معايرة المعدات.",solution:"يولّد نظام أتلانتيس حزمة تدقيق كاملة لمراجعات أرامكو بضغطة زر واحدة، شاملةً تاريخ فحص الأصول وسجلات تأهيل الأفراد وشهادات المعايرة."}],modules:[{title:"جدولة الفحص وإدارة أوامر العمل",description:"أتمتة احتساب فترات الفحص وفقًا لمعايير API 510 و API 570 و API 653 ومتطلبات سعودي أرامكو SAEP. تخصيص الفنيين والمعدات لأوامر العمل في ثوانٍ.",features:["احتساب تلقائي لفترات API","جدولة الفحص القائم على المخاطر","مصفوفة توفر الفنيين","تدفقات اعتماد أوامر العمل","وصول ميداني للمفتشين"]},{title:"تتبع شهادات الأفراد",description:"مركز سجلات شهادات ASNT و ISO 9712 و CSWIP والمؤهلات المعتمدة لدى أرامكو، مع تنبيهات تلقائية قبل الانتهاء.",features:["تنبيهات انتهاء ASNT و CSWIP","متابعة ISO 9712","مصفوفة المؤهلات لأرامكو ومعادن","رسائل تذكير تلقائية بالتجديد","تصدير شهادات PDF جاهزة للتدقيق"]},{title:"إصدار تقارير الفحص",description:"أنشئ تقارير فحص احترافية بصيغة PDF وفقًا لمعايير API و ASME وقوالب أرامكو SAEP-1142.",features:["قوالب تقارير API 510","صيغ فحص الأنابيب API 570","تقارير فحص الخزانات API 653","قوالب أرامكو SAEP-1142","تكامل التوقيع الرقمي والختم"]},{title:"إدارة بيانات التآكل",description:"سجّل قراءات السماكة ومعدلات التآكل وحسابات العمر المتبقي لأصول العملاء في الرياض ومحيطها.",features:["قاعدة بيانات قياسات السماكة بالموجات فوق الصوتية","مخططات اتجاه معدل التآكل","احتساب العمر المتبقي","تنبيهات نسبة فقدان السماكة","تصدير تقييم API 579"]},{title:"سجل الأصول وإدارة المعدات",description:"احتفظ بسجل رقمي كامل للأصول مع تتبع حالة معايرة المعدات وأدوات الفحص.",features:["هيكلية أصول مرتبطة بمخططات P&ID","متتبع تواريخ استحقاق المعايرة","وسم الأصول برموز QR","سجل فحص تاريخي لكل أصل","تصنيف المخاطر"]},{title:"لوحة الامتثال",description:"رؤية فورية لامتثال متطلبات أرامكو ومعادن وشركة الكهرباء السعودية في الرياض.",features:["لوحة تنبيه الفحوصات المتأخرة","نظرة عامة على حالة الامتثال متعدد العملاء","تقارير مؤشرات الأداء الرئيسية","تنبيهات تغييرات اللوائح","تقارير ملخص تنفيذي"]}],integrations:["متابعة تأهيل سعودي أرامكو SAEP-1112","تقارير بصيغة SAEP-1142","تكامل SAP S/4HANA","بوابة موردي أرامكو","صيغ تقارير شركة معادن","متطلبات شركة الكهرباء السعودية","ربط مع نظام الجودة الخاص بنيوم والبحر الأحمر","تكامل ساسو SASO"],faqs:[{question:"هل يدعم النظام مشاريع نيوم والبحر الأحمر الناشئة؟",answer:"نعم. يحتوي النظام على قوالب مرنة قابلة للتعديل وفق متطلبات أي عميل، بما في ذلك مشاريع البنية التحتية الكبرى مثل نيوم والبحر الأحمر التي تتطلب صيغ تقارير خاصة. كما يدعم النظام متطلبات الفحص للطاقة المتجددة بما في ذلك توربينات الرياح ومحطات الطاقة الشمسية."},{question:"كيف يتعامل النظام مع متطلبات شركة معادن للفحص في مواقع التعدين؟",answer:"يتضمن النظام وحدة مخصصة لعمليات الفحص في مواقع التعدين، تشمل قوالب تقارير معتمدة لشركة معادن، ومتابعة شهادات الفنيين العاملين في بيئات تعدين الفوسفات والذهب والألمنيوم. يدعم النظام أيضًا تكامل بوابة موردي معادن لتسليم التقارير إلكترونيًا."},{question:"هل يدعم النظام إصدار تقارير ثنائية اللغة (العربية والإنجليزية)؟",answer:"نعم. يدعم النظام إصدار تقارير ثنائية اللغة في نفس الملف PDF، مع إمكانية اختيار اللغة الأساسية لكل عميل. يستخدم العديد من عملاء أرامكو في الرياض التقارير ثنائية اللغة لأغراض التدقيق الداخلي والإيداع لدى الهيئات التنظيمية."},{question:"ما مدة التنفيذ لشركة فحص في الرياض؟",answer:"يستغرق التنفيذ النموذجي لشركة فحص في الرياض من أربعة إلى ستة أسابيع، شاملًا ترحيل البيانات التاريخية وتدريب الفرق وتكامل قوالب التقارير الخاصة بأرامكو. يوفر فريق التنفيذ تدريبًا في الموقع باللغة العربية لضمان اعتماد سريع من قبل الفنيين الميدانيين."}],ui:i})}export{s as default};
